import os
import random
import numpy as np
import torch


class Config:
    # =========================================================================
    # File Paths & Directories
    # =========================================================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working"

    # Specific checkpoint/cache directory for this solution iteration
    CHECKPOINT_DIR = os.path.join(WORKING_DIR, "idea_2")

    # Metadata file paths (generated by previous steps)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test.csv")

    # Submission output
    SUBMISSION_PATH = "submission.csv"

    # =========================================================================
    # Data & Model Hyperparameters
    # =========================================================================
    # Input volume depth (number of z-slices in the scan)
    Z_DIM = 65

    # Spatial dimensions for training crops
    PATCH_SIZE = 512

    # Number of workers for data loading
    NUM_WORKERS = 2

    # =========================================================================
    # Training Hyperparameters
    # =========================================================================
    # Random seed for reproducibility
    SEED = 42

    # Batch size (set to 32 as per solution design)
    BATCH_SIZE = 32

    # Learning rate for Adam optimizer
    LEARNING_RATE = 1e-3

    # Number of training epochs
    EPOCHS = 20

    # Positive class weight for BCEWithLogitsLoss to handle imbalance
    POS_WEIGHT = 2.0

    # =========================================================================
    # Inference Hyperparameters
    # =========================================================================
    # Threshold search range for optimizing F0.5 score
    THRESHOLD_START = 0.1
    THRESHOLD_END = 0.9
    THRESHOLD_STEP = 0.05

    @staticmethod
    def setup():
        """
        Initializes the environment:
        1. Creates necessary working directories.
        2. Sets random seeds for reproducibility.
        """
        # Create checkpoint directory
        os.makedirs(Config.CHECKPOINT_DIR, exist_ok=True)

        # Set seeds
        random.seed(Config.SEED)
        np.random.seed(Config.SEED)
        torch.manual_seed(Config.SEED)
        if torch.cuda.is_available():
            torch.cuda.manual_seed(Config.SEED)
            torch.cuda.manual_seed_all(Config.SEED)
            # Ensure deterministic behavior for cuDNN
            torch.backends.cudnn.deterministic = True
            torch.backends.cudnn.benchmark = False
